// GENERATED by scripts/build-html.mjs from docs/annotator_guide.md. Edit the .md, then `npm run build:html`.
export const GUIDE_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<title>Annotator guide</title>\n<style>\n:root { --paper:#f7f3ea; --card:#fbf8f2; --ink:#1f1b16; --ink-2:#4a4238; --muted:#8a7f70; --rule:#d9cfbd; --red:#b3322a; --mark:#f6e3a1;\n  --serif:\"Iowan Old Style\",\"Palatino Linotype\",Palatino,\"Book Antiqua\",Georgia,Cambria,serif;\n  --sans:system-ui,-apple-system,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif; --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; }\n@media (prefers-color-scheme: dark) { :root { --paper:#1b1915; --card:#211e19; --ink:#ebe4d6; --ink-2:#c9bfae; --muted:#8f8676; --rule:#3a352d; --red:#e0685c; --mark:#5a4a1c; } }\n* { box-sizing: border-box; }\nhtml, body { margin: 0; background: var(--paper); color: var(--ink); }\nbody { font-family: var(--sans); font-size: 16px; line-height: 1.55; }\n.wrap { max-width: 760px; margin: 0 auto; padding: 24px 16px 80px; }\nnav { font-size: 13px; color: var(--muted); border-bottom: 1px solid var(--rule); padding-bottom: 10px; margin-bottom: 8px; display: flex; flex-wrap: wrap; gap: 4px 12px; }\nnav a { color: var(--ink-2); }\nh1 { font-family: var(--serif); font-weight: 600; font-size: 30px; line-height: 1.2; margin: 18px 0 8px; }\nh1 + p { color: var(--ink-2); font-size: 17px; }\nh2 { font-family: var(--serif); font-weight: 600; font-size: 23px; margin: 40px 0 8px; padding-top: 12px; border-top: 1px solid var(--rule); }\nh3 { font-size: 13px; text-transform: uppercase; letter-spacing: .07em; color: var(--red); margin: 26px 0 6px; }\nh4 { font-size: 15px; margin: 18px 0 4px; }\na { color: var(--red); }\ncode { font-family: var(--mono); font-size: .88em; background: var(--card); border: 1px solid var(--rule); border-radius: 3px; padding: 0 3px; }\nkbd { font-family: var(--mono); font-size: 12px; border: 1px solid var(--rule); border-bottom-width: 2px; border-radius: 3px; padding: 0 5px; background: var(--card); }\nblockquote { margin: 12px 0; padding: 10px 16px; background: var(--card); border: 1px solid var(--rule); border-left: 3px solid var(--red); font-family: var(--serif); font-size: 17px; line-height: 1.6; }\nblockquote p { margin: .3em 0; }\nul, ol { padding-left: 1.3em; } li { margin: 3px 0; }\n.tw { overflow-x: auto; margin: 10px 0; }\ntable { border-collapse: collapse; font-size: 14.5px; width: 100%; }\nth, td { border-bottom: 1px solid var(--rule); padding: 6px 8px; text-align: left; vertical-align: top; }\nth { font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: var(--ink-2); }\nhr { border: 0; border-top: 1px solid var(--rule); margin: 28px 0; }\nstrong { font-weight: 650; }\n</style>\n</head>\n<body><div class=\"wrap\">\n<nav><a href=\"#the-one-page-version\">The one-page version</a><a href=\"#where-does-the-resistance-come-from\">Where does the resistance come from?</a><a href=\"#kinds-of-obstacle-cheat-sheet\">Kinds of obstacle: cheat sheet</a><a href=\"#eight-worked-examples\">Eight worked examples</a><a href=\"#six-tricky-cases\">Six tricky cases</a><a href=\"#how-the-work-is-organised\">How the work is organised</a></nav>\n<h1 id=\"annotator-guide-what-stands-in-the-way\">Annotator guide: What Stands in the Way</h1>\n<p>Thank you for helping! This guide takes about 10 minutes to read. Keep it open in another tab while you work. The <strong>Guide</strong> link at the top of the labelling page brings you back here.</p>\n<h2 id=\"the-one-page-version\">The one-page version</h2>\n<p>You will read short passages (about 350 words) from English novels and stories published between 1800 and 1929. For each one you answer up to three quick questions. Most passages take <strong>25 to 35 seconds</strong>.</p>\n<p><strong>The core rule.</strong> A passage has a <em>plot obstacle</em> when all three of these are true:</p>\n<ol><li><strong>Someone wants something.</strong> A character has a goal: to get somewhere, marry someone, learn a secret, escape, save someone, keep a home. The goal can be stated or just clearly implied.</li><li><strong>Something is in the way.</strong> A thing, a person, a rule, a feeling, or a lack (of money, news, light) blocks it, delays it, or puts it in danger.</li><li><strong>It matters for what happens next.</strong> The obstacle is part of the action. It changes what people do, feel or decide. It is not just scenery.</li></ol>\n<p>If any of the three is missing, the answer is <strong>No</strong>.</p>\n<p><strong>The three questions.</strong></p>\n<div class=\"tw\"><table><thead><tr><th>#</th><th>Question</th><th>Answers</th><th>Keys</th></tr></thead><tbody><tr><td>1</td><td>Is there a plot obstacle?</td><td>Yes / No / Can't tell</td><td><kbd>y</kbd> <kbd>n</kbd> <kbd>c</kbd></td></tr><tr><td>2</td><td>What kind of thing is in the way? (only if Yes)</td><td>one of 9 kinds, or Other</td><td><kbd>1</kbd>–<kbd>9</kbd>, <kbd>o</kbd></td></tr><tr><td>2b</td><td>Why does the communication fail? (only for kind 2)</td><td>6 choices</td><td><kbd>Shift</kbd>+<kbd>1</kbd>–<kbd>6</kbd></td></tr><tr><td>3</td><td>Where does the resistance come from? (only if Yes)</td><td>Material / Social / Inner</td><td><kbd>m</kbd> <kbd>s</kbd> <kbd>i</kbd></td></tr></tbody></table></div>\n<p>Then press <kbd>Enter</kbd>. Highlighting evidence and writing a note are optional.</p>\n<p><strong>Five habits that matter most.</strong></p>\n<ul><li>Judge the <strong>bordered passage</strong>. The grey text before and after is there to help you understand it.</li><li>If there are several obstacles, pick the <strong>closest</strong> one: the thing that, if you took it away, would let the character go ahead. If two are equally close, pick the one the passage spends more time on.</li><li>A thing that is only <strong>mentioned</strong> is not an obstacle. A letter being written is not an obstacle; a letter that never arrives is.</li><li><strong>When you are unsure, choose Can't tell.</strong> It is an honest answer, not a failure.</li><li><strong>Don't look anything up.</strong> You will never see the title or author. Please don't search for the passage, and judge only what is on the page.</li></ul>\n<h2 id=\"where-does-the-resistance-come-from\">Where does the resistance come from?</h2>\n<p>This is the most important question in the study. Ask yourself: <em>if this obstacle pushes back, what is doing the pushing?</em></p>\n<div class=\"tw\"><table><thead><tr><th>Choose</th><th>When the resistance comes from…</th><th>Plain examples</th></tr></thead><tbody><tr><td><strong>Material</strong> <kbd>m</kbd></td><td>the physical world: places, distance, weather, darkness, bodies, objects, machines</td><td>a flooded road; a broken axle; fever; a letter lost in the post; a lamp that goes out</td></tr><tr><td><strong>Social</strong> <kbd>s</kbd></td><td>other people and society: someone opposing, rules, class, money, law, a lie or a secret kept by someone else</td><td>a father who forbids the marriage; a debt; \"a governess can't marry the heir\"; a rival who hides the letter</td></tr><tr><td><strong>Inner</strong> <kbd>i</kbd></td><td>the character's own mind: fear, pride, guilt, shyness, doubt, indecision</td><td>\"she was too proud to ask\"; \"he could not bring himself to speak\"</td></tr></tbody></table></div>\n<p>Each kind of obstacle has a <strong>usual</strong> source (the page shows it as a hint after you pick a kind). Go with the usual one unless the passage clearly says otherwise. For example, an illness that the passage presents as \"nerves\" or imagined could be inner.</p>\n<h2 id=\"kinds-of-obstacle-cheat-sheet\">Kinds of obstacle: cheat sheet</h2>\n<div class=\"tw\"><table><thead><tr><th>Key</th><th>Kind</th><th>In the way is…</th><th>Usual source</th></tr></thead><tbody><tr><td>1</td><td>Distance / travel</td><td>being far away; a slow, hard or broken journey; a missed coach or train; a road that can't be used</td><td>material</td></tr><tr><td>2</td><td>Communication / information</td><td>a message that fails, is late, lost, hidden, forged or misread; a secret; not knowing a key fact; mistaken identity</td><td>depends on the cause (below)</td></tr><tr><td>3</td><td>Darkness / can't see</td><td>night, fog, no light, hiding in the dark: not being able to see or be seen</td><td>material</td></tr><tr><td>4</td><td>Illness / body / death</td><td>sickness, injury, weakness, pregnancy, dying, a death</td><td>material</td></tr><tr><td>5</td><td>Money / property / law</td><td>poverty, debt, rent, wills and inheritance, contracts, courts, police</td><td>social</td></tr><tr><td>6</td><td>Social rank / rules</td><td>class, manners, reputation, marriage rules, what a woman or servant \"may not\" do, a parent's authority as a rule</td><td>social</td></tr><tr><td>7</td><td>A person opposing</td><td>a particular person who actively blocks, tricks, threatens or fights the character</td><td>social</td></tr><tr><td>8</td><td>Inner state</td><td>the character's own fear, doubt, pride, guilt, shyness or indecision</td><td>inner</td></tr><tr><td>9</td><td>Nature / weather</td><td>storms, floods, snow, the sea, wild land, animals</td><td>material</td></tr><tr><td>o</td><td>Other</td><td>a real obstacle that fits none of the above (add a short note)</td><td>you decide</td></tr></tbody></table></div>\n<p><strong>Person opposing or Social rank?</strong> If a particular person acts against the character (locks her in, lies, attacks), choose <em>A person opposing</em>. If the problem is a rule about class or propriety (even when a parent enforces it), choose <em>Social rank / rules</em>. The source is social either way.</p>\n<p><strong>Why does the communication fail?</strong> (only when you chose kind 2)</p>\n<div class=\"tw\"><table><thead><tr><th>Key</th><th>Cause</th><th>Example</th><th>Usual source</th></tr></thead><tbody><tr><td>Shift+1</td><td>No way to send it / too slow</td><td>no telegraph office; the post hasn't come; too far away</td><td>material</td></tr><tr><td>Shift+2</td><td>Lost or mixed up by accident</td><td>the letter went astray; it arrived after she left</td><td>material</td></tr><tr><td>Shift+3</td><td>Kept back on purpose</td><td>a secret; a letter intercepted, burned or forged; a lie</td><td>social</td></tr><tr><td>Shift+4</td><td>Misunderstood</td><td>the message is misread; someone is taken for someone else</td><td>social</td></tr><tr><td>Shift+5</td><td>A message solves it</td><td>the telegram arrives just in time and removes the problem</td><td>you decide</td></tr><tr><td>Shift+6</td><td>None of these / unclear</td><td>it is about information, but none of these fits</td><td>you decide</td></tr></tbody></table></div>\n<p>If the character keeps the secret themselves (won't write, won't ask, won't tell), the source is <strong>inner</strong>.</p>\n<h2 id=\"eight-worked-examples\">Eight worked examples</h2>\n<p>Each example shows a short quote from the passage; on the real page you would see the whole passage.</p>\n<h3 id=\"1-a-letter-that-never-arrived\">1. A letter that never arrived</h3>\n<blockquote><p>\"I sent it by Margaret Nugent, and she told me that you scoffed at it, and cast it to the winds.\"</p>\n<p>\"I never received that letter, darling,\" he replied, starting up, a bitter imprecation on his lips against his false cousin.</p></blockquote>\n<p><strong>Yes · Communication / information · Kept back on purpose · Social.</strong> Elaine and Harold lost each other because the letter never reached him. His jealous cousin carried it and lied about it. A message withheld on purpose by another person is social. It happened in the past, but it still shapes the scene: they part as \"lost\" lovers.</p>\n<h3 id=\"2-a-gale-between-the-castaways-and-their-rescue\">2. A gale between the castaways and their rescue</h3>\n<blockquote><p>\"I doubt if they will, however, venture to send a boat on shore, until the wind moderates a little.\"</p></blockquote>\n<p><strong>Yes · Nature / weather · Material.</strong> The family on the island wants to be rescued by the ship they have just sighted. The rising gale keeps the ship from sending a boat, and by the end of the passage the ship is sailing away (\"She is leaving us\").</p>\n<h3 id=\"3-lost-lamp-in-a-coal-mine\">3. Lost lamp in a coal mine</h3>\n<blockquote><p>The lamp had disappeared into a pool of black water and could no longer be located. All was pitch-dark around them.</p></blockquote>\n<p><strong>Yes · Darkness / can't see · Material.</strong> The boys need to find their way out of the mine. Without light they cannot move safely (\"You may go into one of the holes\"), so they make paper tapers and hunt for a torch.</p>\n<h3 id=\"4-too-proud-to-ask\">4. Too proud to ask</h3>\n<blockquote><p>She was assured, but she would have given much to have been able to ask him questions. She could not; her pride forbade,</p></blockquote>\n<p><strong>Yes · Inner state · Inner.</strong> She wants answers, and nothing outside her stands in the way. Her own pride stops her, and she walks off without asking.</p>\n<h3 id=\"5-beneath-him-in-station\">5. \"Beneath him in station\"</h3>\n<blockquote><p>Should she not now hold fast, as she had before, and save him the second time from this girl who was beneath him in station and who would drag him down to her level, and so perhaps ruin him?</p></blockquote>\n<p><strong>Yes · Social rank / rules · Social.</strong> Oliver wants to marry Madge. His mother objects because the girl is of a lower class, and she tells him not to ask her yet. The barrier is a class rule, even though his mother enforces it. It matters: Oliver decides to keep his engagement secret.</p>\n<h3 id=\"6-the-mortgage\">6. The mortgage</h3>\n<blockquote><p>Besides, he thinks now that he may have to stay out of college a year, if not give it up altogether. It's the mortgage on the house.</p></blockquote>\n<p><strong>Yes · Money / property / law · Social.</strong> In her letter, Eunice explains that her hope of college (and her brother's) is blocked by trouble over the mortgage. Priscilla is moved and wishes she could pay it off. Obstacles reported in a letter or in dialogue count.</p>\n<h3 id=\"7-a-description-of-a-mountain\">7. A description of a mountain</h3>\n<blockquote><p>Off in the distance one great mountain rose far up above the others, and stood like a great giant among its fellows.</p></blockquote>\n<p><strong>No.</strong> A mother and son look at the Great Stone Face, and she tells him an old prophecy. The boy has a wish, but nothing stands in the way of anything. Beautiful description is not an obstacle.</p>\n<h3 id=\"8-a-passage-you-can-t-read\">8. A passage you can't read</h3>\n<blockquote><p>et assignatis suis contra omnes gentes Warrantizabimus et defendemus imperpetuum.</p></blockquote>\n<p><strong>Can't tell.</strong> This passage is almost entirely a legal document in Latin. When you cannot understand a passage well enough to judge it (another language, scrambled text, a fragment), choose Can't tell.</p>\n<h2 id=\"six-tricky-cases\">Six tricky cases</h2>\n<h3 id=\"mention-or-function\">Mention or function?</h3>\n<blockquote><p>Come, sit down by the fire, Ada, and read me again the letter you received from your brother the other day; that will help to while away the time till they come.</p></blockquote>\n<p>The letter here is only <strong>mentioned</strong>. It does nothing to anyone's plans. Later in the same passage, though, the father arrives with news that the brother \"sent me a telegram to say he'd missed the train, and will be here to-morrow\". The family wanted him home tonight, and a missed train stopped it. That is a real obstacle: <strong>Yes · Distance / travel · Material.</strong> The telegram itself works fine; it is just how they hear the news.</p>\n<h3 id=\"atmosphere-or-something-that-stops-someone\">Atmosphere, or something that stops someone?</h3>\n<blockquote><p>a London fog, when the omnibuses ceased to ply, and not even the boldest cabby would undertake to convey Derval to the West India Docks</p></blockquote>\n<p>A long description of fog is usually just atmosphere, so the answer is No. But here the fog stops every cab, and Derval needs to reach his ship. That makes it <strong>Yes · Darkness / can't see · Material</strong> (fog counts as \"can't see\"). Ask: <em>does the darkness, storm or fog actually stop or endanger someone's goal?</em></p>\n<h3 id=\"past-and-what-if-obstacles\">Past and \"what if\" obstacles</h3>\n<p>A <strong>past</strong> obstacle counts if it still shapes what happens in the passage, like the lost letter in example 1. A worry that is over and done (\"his doubts and fears had been removed\") does not.</p>\n<p>A <strong>\"what if\"</strong> counts only if someone acts on it:</p>\n<blockquote><p>\"We'll be snowed up,\" Jack again predicted, gloomily.</p></blockquote>\n<p>The boys grumble, sleep and set off again in the morning. Nobody does anything because of the prediction, so the prediction alone does <strong>not</strong> make an obstacle.</p>\n<h3 id=\"passages-that-read-like-history-or-an-essay\">Passages that read like history or an essay</h3>\n<p>Some passages read like a history book. Judge them like any story: if a person in the passage tries to do something and is blocked, it counts.</p>\n<blockquote><p>it had been snowing, sleeting, and raining for several days; the roads were impassable, they had no bottom.</p></blockquote>\n<p>Washington wants to march his army at night, but his officers object that the mud will stop the guns and wagons. Then the wind shifts and it turns cold: <strong>Yes · Nature / weather · Material.</strong></p>\n<p>An essay or a general reflection, with no particular character trying to do something, is <strong>No</strong>:</p>\n<blockquote><p>The essence of Puritanism, however, was not its dogmas, but its strenuous earnestness, its exaltation of self-denial, and its distrust of the guidance of the senses.</p></blockquote>\n<h3 id=\"comic-obstacles-count\">Comic obstacles count</h3>\n<blockquote><p>The barrel went down, and I went up.</p></blockquote>\n<p>The Colonel is left dangling from a pulley rope, and he must \"get down before those men came back from dinner\". It is played for laughs, but he wants something and is stuck: <strong>Yes · Other · Material</strong> (being stuck in mid-air fits none of the nine kinds). His pride (he won't wait for help) is part of the story too. The closest obstacle, though, is the rope he is hanging from.</p>\n<h3 id=\"several-obstacles-pick-the-closest-one\">Several obstacles: pick the closest one</h3>\n<blockquote><p>She knows that he cannot, under the most favorable conditions, reach her in less than a month.</p></blockquote>\n<p>Rob learns by coded telegram that his father, far away in China, is dangerously ill and wants to see him. Illness is why he must go. The telegram works perfectly. What stands between Rob and his father is the distance: <strong>Yes · Distance / travel · Material.</strong> Ask: <em>if I took this one thing away, could the character go ahead?</em></p>\n<h2 id=\"how-the-work-is-organised\">How the work is organised</h2>\n<ol><li><strong>Read this guide</strong> (10 minutes).</li><li><strong>Practice: 20 passages.</strong> After each answer you see a reference answer and a short \"why\". This is for learning, so don't worry about mistakes.</li><li><strong>Check: 20 passages</strong>, without feedback. If your answers mostly agree with the reference, the main set unlocks. If not, you see the passages where you differed, with the reasons, and you can take one <strong>second check</strong> with 20 new passages.</li><li><strong>Main set: about 500 passages</strong>, in random order. A few of them are also labelled by another person, so we can measure agreement. That is normal, and it is not a test of you.</li></ol>\n<p><strong>Time.</strong> Plan on about 30 seconds per passage: 10 to 15 minutes each for practice and the check, and about 4 hours for the main set. Spread that over several days, in sittings of 20 to 30 minutes. The header shows how much time is left.</p>\n<p><strong>Breaks.</strong> Every answer is saved as soon as you press Enter. Press <kbd>b</kbd> (or <strong>Break</strong>) to pause the timer. You can close the tab at any time and come back later with <strong>your personal link</strong>, on any device. Bookmark it, and don't share it: it is your identity in the study.</p>\n<p><strong>Phones and tablets.</strong> Everything works by tapping. On a phone the passage comes first, the questions are below it, and the Submit button stays at the bottom of the screen.</p>\n<p><strong>Mistakes.</strong> Press <kbd>u</kbd> (or <strong>Undo last</strong>) to reopen your most recent answer in the main set. Practice and check answers can't be changed.</p>\n<p><strong>All the keys.</strong> <kbd>y</kbd> <kbd>n</kbd> <kbd>c</kbd> obstacle · <kbd>1</kbd>–<kbd>9</kbd> <kbd>o</kbd> kind · <kbd>Shift</kbd>+<kbd>1</kbd>–<kbd>6</kbd> communication cause · <kbd>m</kbd> <kbd>s</kbd> <kbd>i</kbd> source · <kbd>e</kbd> add selected words as evidence · <kbd>t</kbd> note · <kbd>Enter</kbd> submit · <kbd>u</kbd> undo · <kbd>q</kbd> switch set · <kbd>b</kbd> break · <kbd>g</kbd> guide · <kbd>?</kbd> help.</p>\n<p><strong>Questions?</strong> Ask the student who invited you. If a passage is upsetting or broken, write a short note (<kbd>t</kbd>) and choose Can't tell.</p>\n</div></body>\n</html>\n";
